INSERT INTO cities (name, slug, description, shortDescription, highlights, bestTime, region, accentColor, previewImageUrl, isPublished, createdAt, updatedAt) VALUES ('Beijing', 'beijing', 'The capital of China, blending ancient imperial heritage with modern metropolis. Explore the Great Wall, Forbidden City, and vibrant hutong neighborhoods.', 'Imperial heritage meets modern China', 'Great Wall, Forbidden City, Summer Palace, Temple of Heaven', 'April-May, September-October', 'North China', '#D4A574', '/uploads/images/b981b637623588d828999e0bea129759c6c58e4944df9403237a43584f762392.jpg', true, NOW(), NOW());
INSERT INTO cities (name, slug, description, shortDescription, highlights, bestTime, region, accentColor, previewImageUrl, isPublished, createdAt, updatedAt) VALUES ('Shanghai', 'shanghai', 'China\'s most cosmopolitan city, showcasing futuristic skyscrapers alongside historic French Concession. Experience world-class dining, art, and nightlife.', 'Modern metropolis with artistic soul', 'The Bund, Yu Garden, French Concession, Oriental Pearl Tower', 'April-May, September-October', 'East China', '#8B4513', '/uploads/images/cbe08dfd20aa279904886c7dc465ee9f925a587bf96b948262f4f844db8f6c2f.jpg', true, NOW(), NOW());
INSERT INTO cities (name, slug, description, shortDescription, highlights, bestTime, region, accentColor, previewImageUrl, isPublished, createdAt, updatedAt) VALUES ('Guilin', 'guilin', 'Famous for dramatic karst mountains and the serene Li River. A painter\'s paradise with traditional cormorant fishing and bamboo rafting.', 'Landscape painting come to life', 'Li River, Karst Mountains, Cormorant Fishing, Reed Flute Cave', 'April-May, September-October', 'South China', '#6B8E23', '/uploads/images/3.jpg', true, NOW(), NOW());
INSERT INTO cities (name, slug, description, shortDescription, highlights, bestTime, region, accentColor, previewImageUrl, isPublished, createdAt, updatedAt) VALUES ('Hangzhou', 'hangzhou', 'Home to the enchanting West Lake, surrounded by tea plantations and ancient temples. A city of poets and artists.', 'Romantic lakeside paradise', 'West Lake, Dragon Well Tea, Lingyin Temple, Pagodas', 'March-May, September-November', 'East China', '#4A90E2', '/uploads/images/fd0dc0ec7bb7780fe7cd7e76de04b3b2b08bfd684af2afa458a4e414fa05140f.jpg', true, NOW(), NOW());
INSERT INTO cities (name, slug, description, shortDescription, highlights, bestTime, region, accentColor, previewImageUrl, isPublished, createdAt, updatedAt) VALUES ('Xian', 'xian', 'Ancient capital along the Silk Road, home to the Terracotta Army. Discover thousands of years of Chinese history and culture.', 'Ancient Silk Road capital', 'Terracotta Army, City Walls, Big Wild Goose Pagoda, Muslim Quarter', 'April-May, September-October', 'Central China', '#C41E3A', '/uploads/images/802718d3cf4e06d977a7ce89b9b5b059961bd30dd185cfc85d50f4b517d86888.jpg', true, NOW(), NOW());
INSERT INTO experienceTypes (name, slug, description, icon, sortOrder, isPublished, createdAt, updatedAt) VALUES ('Cultural Heritage', 'cultural-heritage', 'Immerse yourself in China\'s rich cultural traditions', 'museum', 1, true, NOW(), NOW());
INSERT INTO experienceTypes (name, slug, description, icon, sortOrder, isPublished, createdAt, updatedAt) VALUES ('Nature & Adventure', 'nature-adventure', 'Explore stunning landscapes and outdoor activities', 'mountain', 2, true, NOW(), NOW());
INSERT INTO experienceTypes (name, slug, description, icon, sortOrder, isPublished, createdAt, updatedAt) VALUES ('Culinary Journey', 'culinary-journey', 'Taste authentic regional cuisines and cooking traditions', 'utensils', 3, true, NOW(), NOW());
INSERT INTO experienceTypes (name, slug, description, icon, sortOrder, isPublished, createdAt, updatedAt) VALUES ('Urban Exploration', 'urban-exploration', 'Discover modern cities and contemporary culture', 'building', 4, true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Great Wall Sunrise Trek', 'great-wall-sunrise-trek', 'Hike the Great Wall at dawn to witness a breathtaking sunrise over the mountains. This guided trek includes breakfast at a local village.', 'Sunrise hike on the Great Wall', '6 hours', 'Moderate', '4-12 people', '$120 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Forbidden City Private Tour', 'forbidden-city-private-tour', 'Exclusive after-hours access to the Forbidden City with a historian guide. Explore imperial palaces and learn about 500 years of Chinese history.', 'After-hours imperial palace tour', '4 hours', 'Easy', '2-8 people', '$200 per group', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Hutong Cooking Class', 'hutong-cooking-class', 'Learn to cook traditional Beijing dishes in a local family\'s kitchen. Includes market visit and lunch with the family.', 'Cook Beijing cuisine in a hutong home', '5 hours', 'Easy', '2-6 people', '$90 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Bund Architecture Walk', 'bund-architecture-walk', 'Guided architectural tour of Shanghai\'s iconic Bund, featuring colonial buildings, modern skyscrapers, and the Huangpu River.', 'Explore Shanghai\'s architectural landmarks', '3 hours', 'Easy', '4-15 people', '$60 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('French Concession Art Tour', 'french-concession-art-tour', 'Discover galleries, street art, and creative spaces in Shanghai\'s artistic French Concession neighborhood.', 'Art and culture in French Concession', '4 hours', 'Easy', '2-10 people', '$85 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Shanghai Dim Sum Experience', 'shanghai-dim-sum-experience', 'Traditional dim sum breakfast at a historic teahouse, followed by a visit to a local market and cooking demonstration.', 'Authentic dim sum and tea culture', '3.5 hours', 'Easy', '2-8 people', '$75 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Li River Bamboo Rafting', 'li-river-bamboo-rafting', 'Traditional bamboo raft journey down the Li River, passing dramatic karst mountains and traditional villages.', 'Scenic bamboo raft on the Li River', '4 hours', 'Easy', '2-20 people', '$65 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Karst Mountain Hiking', 'karst-mountain-hiking', 'Trek through stunning karst landscape with panoramic views. Visit remote villages and experience local culture.', 'Hike through karst mountains', '7 hours', 'Moderate', '4-10 people', '$95 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Cormorant Fishing Night Show', 'cormorant-fishing-night-show', 'Witness the ancient art of cormorant fishing by lantern light on the Li River. Includes dinner and traditional performance.', 'Ancient fishing tradition at night', '3 hours', 'Easy', '2-30 people', '$70 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('West Lake Sunrise Boat Tour', 'west-lake-sunrise-boat-tour', 'Private boat tour on West Lake at sunrise, visiting ancient temples and traditional pagodas.', 'Serene sunrise on West Lake', '3 hours', 'Easy', '2-8 people', '$80 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Dragon Well Tea Plantation', 'dragon-well-tea-plantation', 'Visit a Dragon Well tea plantation, learn tea picking and processing, and enjoy a traditional tea ceremony.', 'Tea picking and ceremony experience', '4 hours', 'Easy', '2-12 people', '$70 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Lingyin Temple Meditation', 'lingyin-temple-meditation', 'Guided meditation session at the ancient Lingyin Temple, followed by Buddhist philosophy discussion with a monk.', 'Meditation at ancient Buddhist temple', '3 hours', 'Easy', '2-20 people', '$60 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Terracotta Army Excavation Tour', 'terracotta-army-excavation-tour', 'Comprehensive tour of the Terracotta Army with expert archaeologist. Includes museum and active excavation site.', 'Explore the Terracotta Army', '5 hours', 'Easy', '2-15 people', '$110 per person', true, NOW(), NOW());
INSERT INTO experiences (name, slug, description, shortDescription, duration, difficulty, groupSize, price, isPublished, createdAt, updatedAt) VALUES ('Muslim Quarter Food Tour', 'muslim-quarter-food-tour', 'Street food tasting tour in Xian\'s vibrant Muslim Quarter. Sample dumplings, noodles, and local specialties.', 'Street food adventure in Muslim Quarter', '3 hours', 'Easy', '2-10 people', '$55 per person', true, NOW(), NOW());
